{"cards": [{"node_code": "N_ed613ce01b18f8f6", "definition": "研究港口工程施工过程中的技术管理体系，涵盖技术标准执行、质量检验、安全规范、进度控制及现场技术问题解决。", "boundary": "本节点聚焦于施工过程中的“管理”与“控制”职能，而非具体的物理建造工艺或机械操作。边界在于区分“施工组织与设计”（侧重前期规划与方案编制）和“施工技术”（侧重具体工艺方法）。若内容涉及施工合同、成本核算等纯经济管理，需视树中是否有专门管理节点，若无则侧重技术管理部分归入本节点。", "includes": ["港口工程施工质量控制与验收标准", "施工安全技术措施与现场安全管理", "施工进度计划执行监控与技术协调"], "excludes": ["施工前的总体方案编制与图纸设计", "具体施工机械的操作原理与维修", "施工材料的微观性能研究"], "sibling_distinctions": [{"other_code": "N_faa547cc883b4a2d", "rule": "施工组织与设计侧重施工前的规划、方案确定及资源部署；本节点侧重施工实施过程中的动态管理、质量与安全控制。"}, {"other_code": "N_8c538520e14584dd", "rule": "施工技术侧重具体的工艺方法、操作技巧及物理过程；本节点侧重对这些技术实施过程的规范、监督与管理。"}], "cross_boundary_rule": "若内容涉及“施工技术方案评审”，主挂载施工组织与设计；若涉及“施工过程质量检查”，主挂载本节点。"}, {"node_code": "N_faa547cc883b4a2d", "definition": "研究港口工程施工前的总体部署、施工方案编制、进度计划安排、资源配置及施工总平面布置等规划性工作。", "boundary": "本节点聚焦于施工前的“策划”与“设计”阶段，即如何将设计图纸转化为可执行的施工计划。边界在于区分“施工技术管理”（侧重实施过程控制）和“施工技术”（侧重具体工艺）。若内容涉及施工中的临时变更调整，通常归入施工技术管理或具体技术节点，本节点侧重初始规划。", "includes": ["港口工程施工组织设计文件的编制方法", "施工进度网络图、横道图及关键路径分析", "施工资源（人力、材料、机械）需求计划与调配方案"], "excludes": ["施工过程中的具体工艺操作细节", "施工质量的现场检验与验收", "施工机械的具体选型计算（若侧重设备本身归入施工设备）"], "sibling_distinctions": [{"other_code": "N_ed613ce01b18f8f6", "rule": "本节点侧重施工前的静态规划与方案确定；施工技术管理侧重施工中的动态执行、监控与纠偏。"}, {"other_code": "N_8c538520e14584dd", "rule": "本节点侧重宏观的施工流程安排与逻辑关系；施工技术侧重微观的具体作业方法与工艺参数。"}], "cross_boundary_rule": "若内容涉及“施工总平面布置图”，主挂载本节点；若涉及“施工期间平面动态调整管理”，可关联施工技术管理。"}, {"node_code": "N_52fce7630eb345e3", "definition": "研究港口工程施工中使用的各类机械设备、工具及辅助设施的性能、选型、操作规范、维护保养及新技术应用。", "boundary": "本节点聚焦于施工过程中的“硬件”工具，即机械设备本身及其在港口施工场景下的应用。边界在于区分“施工技术”（侧重工艺方法，设备是手段）和“施工组织”（侧重资源计划，设备是资源之一）。若内容涉及大型施工船舶（如打桩船、起重船）的专用技术，归入本节点；若涉及通用工程机械的基础理论，也归入本节点。", "includes": ["港口专用施工机械（如抓斗、打桩机、起重船）的性能与选型", "施工机械的操作规程、安全使用及日常维护保养", "施工辅助设施（如临时供电、供水、照明）的配置与管理"], "excludes": ["施工机械的制造原理与结构设计（归入机械工业或船舶工程）", "施工机械的采购合同与财务折旧", "施工工艺流程的具体步骤描述（归入施工技术）"], "sibling_distinctions": [{"other_code": "N_8c538520e14584dd", "rule": "本节点侧重机械设备本身的特性、选型及操作维护；施工技术侧重利用这些设备完成具体工程实体的工艺方法。"}, {"other_code": "N_faa547cc883b4a2d", "rule": "本节点侧重设备的技术参数与操作规范；施工组织侧重设备在施工计划中的数量配置与时间调度。"}], "cross_boundary_rule": "若内容涉及“施工机械的故障诊断与维修”，主挂载本节点；若涉及“因机械故障导致的施工技术方案变更”，可关联施工技术或管理。"}]}
